head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.procJob;
scwin.gEmpNo = js_emp_no;
scwin.vScrenID = "ULDSTF15451.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Search = function() {
    if (scwin.dateCheck() == false) {
        return;
    }
    var url = "/AtsContactInfo.do?method=listAllReservDisclsObj" + "&FROM_DATE=" + edt_SDate.getValue() + "&TO_DATE=" + edt_EDate.getValue() + "&ISUR_CD=" + "&APPROV_YN=" + $c.stf.getObjectValue(rdo_APPROV_YN) + "&FORM_PROCS_CD=" + $c.stf.getObjectValue(rdo_FORM_PROCS_CD) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.dateCheck = function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};
scwin.fn_SetCode = function() {
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue(vCurDate);
    edt_EDate.setValue(vCurDate);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    $c.stf.setObjectValue(rdo_APPROV_YN, "");
    $c.stf.setObjectValue(rdo_FORM_PROCS_CD, "144/145");
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};
scwin.fn_check = function() {
    var checkCnt = 0;
    for (var i = 1; i <= dts_Grid.getTotalRow(); i++) {
        if (dts_Grid.getCellData(i, "CHECK") == "T") {
            checkCnt++;
        }
    }
    if (checkCnt <= 0) {
        $c.win.alert("선택한 항목이 없습니다.");
        return false;
    }
    return true;
};


/* 
 *  삭제
 */
scwin.fn_Delete = function() {
    //선택한 항목이 있는지 check
    if (scwin.fn_check() == true) {
        scwin.fn_SetHeader();
        var k = 0;
        for (var i = 1; i <= dts_Grid.getTotalRow(); i++) {
            if (dts_Grid.getCellData(i, "CHECK") == "T") {
                k++;
                dts_UpdateList.insertRow();
                dts_UpdateList.setCellData(k, "ACPT_NO", dts_Grid.getCellData(i, "ACPT_NO"));
                dts_UpdateList.setCellData(k, "EMP_NO", scwin.gEmpNo);
            }
        }
        if (!window.confirm($c.stf.getMessageParam("MSG-A006", '총 ' + k + '건을 삭제'))) return;
        scwin.procJob = "예약공시 삭제";
        trs_save.Action = "/DisclosureApproval.do?method=deleteReservDisclsAdm&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_UpdateList)";
        trs_save.Post();
    }
};
scwin.fn_SetHeader = function() {
    dts_UpdateList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=RESERV_DISCLS_OBJ_INOUT";
    dts_UpdateList.reset();
};
scwin.alert_error2 = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        for (var j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) == '0') {
                //'0' 임의로 떨군 INFO 메시지
                if (dtsObj.SrvErrMsg(USER_DEFINE[i], j) == "SESSION_CLOSED") {
                    //로그아웃
                    $c.frame.path("/top").SystemClose();
                    $c.win.alert("세션이 종료되었습니다. 다시 로그인해 주세요.");
                } else {
                    $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
                }
            } else {
                //기존 에러 메시지
                $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar4(edt_SDate, 1);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar4(edt_EDate, 2);
};
scwin.edt_SDate_OnLastChar = function(ch) {
    afterPopUpCalendar(1); //if(시작일>종료일) 종료일=시작일;

};
scwin.edt_EDate_OnLastChar = function(ch) {
    afterPopUpCalendar(2); //if(시작일>종료일) 시작일=종료일;

};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_Grid_OnFail = function() {
    scwin.alert_error2(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    scwin.alert_error2(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_Grid.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.trs_save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    scwin.fn_Search();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.showObj(btn_Excel, false);
    scwin.fn_SetCode();
    scwin.fn_Search();
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    var file_name = "예약공시 내역";
    var today = $c.ut.cGetToday('yyyymmddhhmmss');
    var xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
    $c.data.downloadGridViewOffice(grd_Grid, file_name, xls_path, "8", 0);
};
scwin.btn_DELETE_onclick = function() {
    scwin.fn_Delete();
};
